LANGUAGE plpgsql
AS $$
DECLARE
    i INT := 1;
    start INT := 120;
    counter INT := 1;
    end INT := 300;
BEGIN
    WHILE (i <= end) LOOP
        INSERT INTO table1 VALUES (start, DEFAULT, counter, start+counter, end);
        i := i+1;
        counter := counter+1;
    END LOOP;
END;
$$;

CREATE OR REPLACE PROCEDURE insertMore()
LANGUAGE plpgsql
AS $$
DECLARE
    start INT;
    counter INT := 1;
    end INT;
BEGIN
    SELECT COUNT(*) INTO end FROM table1;
    SELECT MAX(id)+1 INTO start FROM table1;
    WHILE (counter <= end) LOOP
        INSERT INTO table1 VALUES (start, DEFAULT, counter, start+counter, end);
        counter := counter+1;
    END LOOP;
END;
$$;

